<template>
  <div class="qmp-page" :class="'qmp-' + appearance.variant">
    <header class="qmp-hero"><div><span class="qmp-eyebrow">QGAUSS AI / LETTERS THAT FIND THEIR WAY</span><h1>让每一封信，<br /><mark>都有迹可循。</mark></h1><p>为欢迎、找回密码和第一封体验信，留下一张清楚的投递回执。</p></div><div class="qmp-envelope" aria-hidden="true"><span class="qmp-envelope-orbit"></span><span class="qmp-letter"><i>QGauss AI</i><b>HELLO,<br />YOUR NEXT IDEA.</b><em>✦</em></span><span class="qmp-envelope-face"><b>Q</b></span><span class="qmp-envelope-caption">A LITTLE NOTE. A WARMER SPACE.</span></div></header>
    <div v-if="statusLoading && !overview" class="qmp-card qmp-loading" role="status"><BrandLoader />正在读取发件状态</div>
    <div v-else-if="statusError && !overview" class="qmp-card" role="alert"><h2>暂时没有读到发件状态。</h2><p>{{ statusError }}</p><button class="qmp-primary" type="button" @click="loadStatus">重新读取</button></div>
    <template v-if="overview">
      <section class="qmp-overview-grid"><article class="qmp-card qmp-route-card"><div class="qmp-section-heading"><span class="qmp-number">01</span><div><span class="qmp-eyebrow">YOUR DELIVERY ROUTE</span><h2>先把投递路线布置好。</h2></div><span class="qmp-pill" :class="{ready:overview.transport.canTest}">{{ overview.transport.canTest ? '设置已加载' : '等待准备' }}</span></div><ol class="qmp-route-steps"><li v-for="item in overview.transport.checks" :key="item.id"><span :class="{ready:item.ready}">{{ item.ready ? '✓' : '○' }}</span><div><h3>{{ item.title }}</h3><p>{{ item.description }}</p></div></li></ol><div class="qmp-config-note"><ClientIcon name="lock" /><p>发件账户由部署负责人配置。此页不展示密码，也不修改发件凭据；更新配置后请重新启动站点。</p></div><router-link class="qmp-text-link" to="/settings">核对站点与邮件链接地址 <ClientIcon name="arrowUpRight" /></router-link></article>
        <article class="qmp-card qmp-probe-card"><div class="qmp-section-heading"><span class="qmp-number">02</span><div><span class="qmp-eyebrow">SEND YOURSELF A SMALL HELLO</span><h2>先给自己，寄一声你好。</h2></div></div><p>体验信只发送到当前管理员的注册邮箱。发件服务器接受后，请亲自到邮箱确认，也看看垃圾邮件。</p><div class="qmp-recipient"><span>你的收件地址</span><strong>{{ overview.operatorMailbox }}</strong></div>
          <div v-if="probe" class="qmp-probe-receipt" aria-live="polite"><span class="qmp-pill" :class="'qmp-state-' + probe.status">{{ mailStatus(probe.status) }}</span><strong>{{ probe.confirmedAt ? '你已确认收到这封信。' : probe.status === 'sent' ? '发件服务器已接受，请到邮箱确认。' : probe.status === 'unknown' ? '尚未确认服务器是否接受，请先检查邮箱。' : '最近一次体验信的投递状态' }}</strong><time :datetime="probe.createdAt">{{ mailDate(probe.createdAt) }}</time><p v-if="probe.explanation">{{ probe.explanation }}</p><button v-if="probe.canConfirm && !probe.confirmedAt" class="qmp-secondary" type="button" :disabled="confirmPending" @click="confirmReceived">{{ confirmPending ? '正在保存确认' : '我已在邮箱收到这封信' }}</button></div>
          <div v-if="probeUncertain" class="qmp-notice" role="status">创建结果尚未确认，可能已经开始投递。请先核对状态，不会自动重复发送。<button type="button" @click="confirmProbeState">核对这次请求</button></div><p v-if="probeError" class="qmp-error" role="alert">{{ probeError }}</p><p v-if="statusError" class="qmp-error" role="alert">{{ statusError }}</p><div class="qmp-probe-actions"><button class="qmp-primary" type="button" :disabled="!overview.transport.canTest || probePending || probeUncertain || probeActive" @click="openProbeReview"><ClientIcon name="mail" />{{ probePending ? '正在创建体验信' : '给自己发一封体验信' }}</button><button class="qmp-secondary" type="button" :disabled="statusLoading" @click="loadStatus">刷新状态</button></div><p class="qmp-small">每次发送都需要明确确认。关闭页面不会撤回已接受的投递；“已接受”不代表一定进入了收件箱。</p></article></section>
      <section class="qmp-metrics" aria-label="全部发件记录概览"><div v-for="item in counterItems" :key="item.id"><span>{{ item.title }}</span><strong>{{ overview.counts[item.id] ?? '—' }}</strong></div></section>
    </template>
    <section class="qmp-card qmp-outbox"><div class="qmp-outbox-heading"><div><span class="qmp-eyebrow">EVERY LETTER HAS A RECEIPT</span><h2>翻一翻，最近的投递回执。</h2><p>仅展示安全的状态信息，邮件正文、密码重置链接和内部变量不会出现在这里。</p></div><button class="qmp-secondary" type="button" :disabled="rowsLoading" @click="loadRows(1)">更新记录</button></div><form class="qmp-filters" @submit.prevent="loadRows(1)"><label><span>投递状态</span><select v-model="filters.status" @change="loadRows(1)"><option value="">全部状态</option><option v-for="option in statusOptions" :key="option.value" :value="option.value">{{ option.title }}</option></select></label><label><span>邮件类型</span><select v-model="filters.template" @change="loadRows(1)"><option value="">全部类型</option><option value="welcome">欢迎信</option><option value="resetPassword">找回密码</option><option value="deliveryProbe">体验信</option></select></label><label class="qmp-search"><span>查找收件地址</span><input v-model="filters.keyword" type="search" placeholder="输入邮箱关键词" maxlength="120" /></label><button class="qmp-primary" type="submit" :disabled="rowsLoading">查找</button></form>
      <div v-if="rowsLoading" class="qmp-list-state" role="status"><span class="qmp-spinner"></span>正在读取投递记录</div><div v-else-if="rowsError" class="qmp-list-state" role="alert"><p>{{ rowsError }}</p><button class="qmp-secondary" type="button" @click="loadRows(page)">重新读取</button></div><div v-else-if="!rows.length" class="qmp-list-state"><span class="qmp-empty-icon">✉</span><h3>这里还没有回执。</h3><p>{{ filters.status || filters.template || filters.keyword ? '试着换个筛选条件。' : '欢迎信、找回密码或体验信开始投递后，会在这里留下记录。' }}</p></div><ol v-else class="qmp-receipts"><li v-for="row in rows" :key="row.id"><span class="qmp-receipt-icon"><ClientIcon :name="row.template === 'resetPassword' ? 'lock' : 'mail'" /></span><div class="qmp-receipt-main"><strong>{{ row.subject }}</strong><span>{{ row.to }}</span><time :datetime="row.createdAt">{{ mailDate(row.createdAt) }}</time></div><span class="qmp-pill" :class="'qmp-state-' + row.status">{{ mailStatus(row.status) }}</span><span class="qmp-attempts">已尝试 {{ row.attempts }} 次</span><button class="qmp-receipt-open" type="button" :aria-label="'查看回执：' + row.subject" @click="openReceipt(row)"><ClientIcon name="arrowUpRight" /></button></li></ol><nav class="qmp-pager" aria-label="邮件记录分页"><span>{{ rowsLoading ? '正在读取记录' : rowsError ? '记录数量尚未确认' : '共 ' + total + ' 条记录' }}</span><button class="qmp-secondary" type="button" :disabled="rowsLoading || page <= 1" @click="loadRows(page - 1)">上一页</button><span>第 {{ page }} 页</span><button class="qmp-secondary" type="button" :disabled="rowsLoading || page * pageSize >= total" @click="loadRows(page + 1)">下一页</button></nav></section>
    <section class="qmp-card qmp-template-card"><div><span class="qmp-eyebrow">THE LETTER BEFORE IT LEAVES</span><h2>把一封信，也写得好看一点。</h2><p>查看使用示意资料渲染的邮件模板，不包含任何真实链接，也不会发送邮件。</p><div class="qmp-template-buttons" aria-label="邮件模板"><button v-for="item in templates" :key="item.id" class="qmp-secondary" :aria-pressed="selectedTemplate?.id === item.id" type="button" @click="selectedTemplate = item">{{ item.title }}</button></div><p v-if="templatesError" class="qmp-error" role="alert">{{ templatesError }}</p></div><div v-if="selectedTemplate" class="qmp-letter-preview"><span class="qmp-preview-tag">模板示意 · 不发送</span><iframe :srcdoc="selectedTemplate.html" :title="selectedTemplate.title + '模板示意'" sandbox tabindex="-1" inert aria-hidden="true"></iframe><details><summary>阅读模板文字</summary><p>{{ selectedTemplate.text }}</p></details></div></section>
    <dialog ref="probeDialog" class="qmp-dialog" aria-labelledby="qmp-probe-title" @cancel="cancelProbeReview"><span class="qmp-eyebrow">ONE LETTER, JUST FOR YOU</span><h2 id="qmp-probe-title">寄出这一声你好？</h2><p>仅发送到当前管理员注册邮箱：<strong>{{ overview?.operatorMailbox }}</strong>。</p><p>点击后会在后台投递，离开页面也不会撤回。请到邮箱查看，再回来确认是否收到。</p><div class="qmp-dialog-actions"><button class="qmp-secondary" type="button" :disabled="probePending" @click="closeProbeReview">返回检查</button><button class="qmp-primary" type="button" :disabled="probePending" @click="sendProbe"><span v-if="probePending" class="qmp-spinner"></span>{{ probePending ? '正在创建' : '确认发送体验信' }}</button></div></dialog>
    <dialog ref="receiptDialog" class="qmp-dialog qmp-receipt-dialog" aria-labelledby="qmp-receipt-title"><template v-if="selectedReceipt"><span class="qmp-eyebrow">YOUR DELIVERY RECEIPT</span><h2 id="qmp-receipt-title">{{ selectedReceipt.subject }}</h2><span class="qmp-pill">{{ mailStatus(selectedReceipt.status) }}</span><dl><div><dt>收件地址</dt><dd>{{ selectedReceipt.to }}</dd></div><div><dt>开始时间</dt><dd>{{ mailDate(selectedReceipt.createdAt) }}</dd></div><div><dt>最近尝试</dt><dd>{{ mailDate(selectedReceipt.lastTriedAt) }}</dd></div><div><dt>服务器接受</dt><dd>{{ mailDate(selectedReceipt.sentAt) }}</dd></div><div><dt>投递次数</dt><dd>{{ selectedReceipt.attempts }}</dd></div></dl><p>{{ selectedReceipt.explanation || '未记录可安全展示的投递说明。' }}</p><p class="qmp-small">回执不包含邮件正文或重置凭证；历史记录也不会提供可点击的找回密码链接。</p><button class="qmp-primary" type="button" @click="receiptDialog?.close()">收好这张回执</button></template></dialog>
  </div>
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { api } from '../../api/client.js';
import { useAuth } from '../../stores/auth.js';
import { useAppearance } from '../../stores/appearance.js';
import ClientIcon from '../../components/reference/ClientIcon.vue';
import BrandLoader from '../../components/design/BrandLoader.vue';
import { mailDate, mailStatus, MAIL_STATUS_OPTIONS } from '../../lib/mail-presentation.js';
import '../../components/design/mail-studio.css';
const auth = useAuth(), appearance = useAppearance();
const overview = ref(null), statusLoading = ref(false), statusError = ref(''), probe = ref(null), probePending = ref(false), probeError = ref(''), probeUncertain = ref(false), confirmPending = ref(false);
const rows = ref([]), rowsLoading = ref(false), rowsError = ref(''), page = ref(1), total = ref(0), pageSize = 8, filters = reactive({ status:'', template:'', keyword:'' });
const templates = ref([]), templatesError = ref(''), selectedTemplate = ref(null), selectedReceipt = ref(null), probeDialog = ref(null), receiptDialog = ref(null);
const statusOptions = MAIL_STATUS_OPTIONS;
const counterItems = [{ id:'queued',title:'等待出发' },{ id:'sending',title:'正在投递' },{ id:'sent',title:'服务器已接受' },{ id:'failed',title:'发送失败' },{ id:'unknown',title:'结果未确认' }];
const probeActive = computed(() => probe.value && (['queued','sending'].includes(probe.value.status) || probe.value.retryScheduled));
let alive = true, readVersion = 0, listVersion = 0, readRequest, listRequest, templateRequest, writeRequest, probeKey = '', pollTimer;
const owner = () => ({ id:auth.user?.id, revision:auth.identityRevision });
const current = value => alive && auth.isAdmin && auth.user?.id === value.id && auth.identityRevision === value.revision;
function scheduleStatus() { clearTimeout(pollTimer); if (alive && probeActive.value) pollTimer = setTimeout(loadStatus, 4000); }
function pauseStatusRead() { readRequest?.abort(); readVersion++; statusLoading.value = false; clearTimeout(pollTimer); }
async function loadStatus() {
  if (!auth.isAdmin || probePending.value || confirmPending.value) return;
  readRequest?.abort(); const request = new AbortController(), stamp = owner(), version = ++readVersion; readRequest = request; statusLoading.value = true; statusError.value = '';
  try { const data = await api.get('/mail/status',{signal:request.signal,retry:false}); if (!current(stamp) || request.signal.aborted || version !== readVersion) return; if (!data?.transport || !data.counts) throw new Error('发件状态尚未确认，请重试。'); const previous = probe.value; overview.value = data; if (!probeUncertain.value) { probe.value = data.recentProbe || null; if (previous?.id === probe.value?.id && (previous?.status !== probe.value?.status || previous?.confirmedAt !== probe.value?.confirmedAt)) void loadRows(page.value); } }
  catch (error) { if (current(stamp) && !request.signal.aborted && version === readVersion) statusError.value = error?.message || '暂时无法读取发件状态。'; }
  finally { if (current(stamp) && version === readVersion) { statusLoading.value = false; scheduleStatus(); } }
}
async function loadRows(target = 1) {
  if (!auth.isAdmin) return;
  listRequest?.abort(); const request = new AbortController(), stamp = owner(), version = ++listVersion; listRequest = request; rowsLoading.value = true; rowsError.value = '';
  const query = new URLSearchParams({page:String(target),pageSize:String(pageSize),...Object.fromEntries(Object.entries(filters).map(([key,value])=>[key,value.trim()]))});
  try { const data = await api.get('/mail/outbox?'+query,{signal:request.signal,retry:false}); if (!current(stamp) || request.signal.aborted || version !== listVersion) return; if (!Array.isArray(data?.items)) throw new Error('回执内容尚未确认。'); rows.value = data.items; total.value = data.total; page.value = data.page; }
  catch (error) { if (current(stamp) && !request.signal.aborted && version === listVersion) rowsError.value = error?.message || '暂时无法读取回执。'; }
  finally { if (current(stamp) && version === listVersion) rowsLoading.value = false; }
}
async function loadTemplates() { templateRequest?.abort(); const request = new AbortController(), stamp = owner(); templateRequest=request; try { const data=await api.get('/mail/templates',{signal:request.signal,retry:false}); if(!current(stamp)||request.signal.aborted)return;if(!Array.isArray(data))throw Error('模板内容尚未确认。');templates.value=data;selectedTemplate.value=data[0]||null;templatesError.value=''; } catch(error){if(current(stamp)&&!request.signal.aborted)templatesError.value=error?.message||'暂时无法读取模板。';} }
async function openProbeReview() { if(!overview.value?.transport.canTest||probePending.value||probeActive.value||probeUncertain.value)return;probeError.value='';await nextTick();probeDialog.value?.showModal(); }
function closeProbeReview() { if(!probePending.value)probeDialog.value?.close(); }
function cancelProbeReview(event) { if(probePending.value)event.preventDefault(); }
async function sendProbe() {
  if(probePending.value||!probeDialog.value?.open||!overview.value?.transport.canTest||probeUncertain.value||probeActive.value)return;
  if(confirmPending.value)return;
  pauseStatusRead();const stamp=owner(),request=new AbortController();writeRequest=request;probePending.value=true;probeError.value='';probeKey=crypto.randomUUID();
  try { const data=await api.post('/mail/probes',{requestKey:probeKey},{signal:request.signal,retry:false});if(!current(stamp))return;if(!data?.id||!data.status)throw Error('创建结果尚未确认');probe.value=data;await loadRows(1);scheduleStatus(); }
  catch(error){if(!current(stamp)||request.signal.aborted)return;probeUncertain.value=!error?.status||error.status>=500;probeError.value=probeUncertain.value?'':error?.message||'暂时无法创建体验信。';}
  finally{if(current(stamp)){probePending.value=false;probeDialog.value?.close();void loadStatus();}}
}
async function confirmProbeState(){if(!probeKey||confirmPending.value)return;const stamp=owner(),request=new AbortController();writeRequest=request;confirmPending.value=true;try{const data=await api.get('/mail/probes/'+encodeURIComponent(probeKey),{signal:request.signal,retry:false});if(!current(stamp))return;probe.value=data;probeUncertain.value=false;probeError.value='';scheduleStatus();}catch(error){if(current(stamp)&&!request.signal.aborted)probeError.value='暂时无法确认这次请求。请先检查邮箱，稍后再次核对。';}finally{if(current(stamp))confirmPending.value=false;}}
async function confirmReceived(){if(!probe.value?.canConfirm||confirmPending.value||probePending.value)return;pauseStatusRead();const stamp=owner(),request=new AbortController();writeRequest=request;confirmPending.value=true;probeError.value='';try{const data=await api.post('/mail/probes/'+encodeURIComponent(probe.value.id)+'/confirm',{}, {signal:request.signal,retry:false});if(!current(stamp))return;probe.value=data;}catch(error){if(current(stamp)&&!request.signal.aborted)probeError.value='收信确认结果尚未保存，请刷新状态后核对。';}finally{if(current(stamp)){confirmPending.value=false;void loadStatus();void loadRows(page.value);}}}
async function openReceipt(row){selectedReceipt.value=row;await nextTick();receiptDialog.value?.showModal();}
function clear(){readRequest?.abort();listRequest?.abort();templateRequest?.abort();writeRequest?.abort();clearTimeout(pollTimer);readVersion++;listVersion++;probeDialog.value?.close();receiptDialog.value?.close();overview.value=probe.value=selectedReceipt.value=selectedTemplate.value=null;rows.value=[];templates.value=[];statusError.value=rowsError.value=probeError.value=templatesError.value='';probePending.value=probeUncertain.value=confirmPending.value=statusLoading.value=rowsLoading.value=false;probeKey='';total.value=0;page.value=1;filters.status=filters.template=filters.keyword='';}
watch(()=>[auth.identityRevision,auth.isAdmin],()=>{clear();if(auth.isAdmin){loadStatus();loadRows(1);loadTemplates();}});
onMounted(()=>{loadStatus();loadRows(1);loadTemplates();});
onBeforeUnmount(()=>{alive=false;clear();});
</script>
